// This file is generated by AI.

// 新建项目对话框: 名称 + 存放位置 + 引擎 (+ 可选模板)。
//
// 项目骨架来自引擎: WebGAL 的"项目"就是一份引擎发行包, 因此这里先选引擎, 再可选地
// 用模板覆盖引擎内置模板。没有任何引擎时不给"创建"按钮, 而是直接引到"引擎"设置页。

import { open } from '@tauri-apps/plugin-dialog';
import { Button, Input } from '@fluentui/react-components';
import { FolderOpenRegular } from '@fluentui/react-icons';
import { useMemo, useState } from 'react';

import { engineLabel } from '../lib/engine';
import { joinPath, sanitizeFolderName } from '../lib/paths';
import { createProject, openProject } from '../project';
import { useAppStore } from '../state/store';
import { AppDialog } from './AppDialog';
import { Select, type SelectOption } from './Select';

interface Props {
  onClose: () => void;
  /** 没有引擎时的出口: 打开设置的"引擎"页 */
  onOpenEngineSettings: () => void;
}

export function NewProjectDialog({ onClose, onOpenEngineSettings }: Props) {
  const settings = useAppStore((s) => s.settings);
  const [name, setName] = useState('');
  const [directory, setDirectory] = useState('');
  const [engineId, setEngineId] = useState(settings.engines[0]?.id ?? '');
  const [templateId, setTemplateId] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const engineOptions: SelectOption[] = settings.engines.map((engine) => ({
    value: engine.id,
    label: engineLabel(engine),
  }));
  const templateOptions: SelectOption[] = [
    { value: '', label: '跟随引擎内置模板' },
    ...settings.templates.map((template) => ({ value: template.id, label: template.name })),
  ];

  const target = useMemo(
    () => (directory && name.trim() ? joinPath(directory, sanitizeFolderName(name.trim())) : ''),
    [directory, name]
  );

  const pickDirectory = async () => {
    const dir = await open({ directory: true, title: '选择项目存放位置' });
    if (typeof dir === 'string') setDirectory(dir);
  };

  const submit = async () => {
    setError(null);
    setBusy(true);
    try {
      const created = await createProject({
        name,
        directory,
        engine: settings.engines.find((engine) => engine.id === engineId) ?? null,
        template: settings.templates.find((template) => template.id === templateId) ?? null,
      });
      // 建完直接打开: 用户按下"创建"就是想开始写
      await openProject(created);
      onClose();
    } catch (e) {
      setError(String(e));
    } finally {
      setBusy(false);
    }
  };

  const canSubmit = name.trim() !== '' && directory !== '' && engineId !== '' && !busy;

  return (
    <AppDialog
      title="新建项目"
      description="由引擎复制出一份完整的项目骨架，可再套用模板。"
      size="small"
      height="auto"
      closeOnBackdrop={!busy}
      onClose={onClose}
      footer={
        <>
          <Button onClick={onClose} disabled={busy}>
            取消
          </Button>
          <Button appearance="primary" onClick={() => void submit()} disabled={!canSubmit}>
            {busy ? '正在创建…' : '创建'}
          </Button>
        </>
      }
    >
      <div className="settings-field">
        <span className="settings-label">项目名称</span>
        <Input value={name} placeholder="显示在游戏标题界面的名称" onChange={(_, data) => setName(data.value)} />
      </div>

      <div className="settings-field">
        <span className="settings-label">存放位置</span>
        <div className="engine-path-row">
          <Input value={directory} readOnly placeholder="选择项目存放的父目录" />
          <Button icon={<FolderOpenRegular />} onClick={() => void pickDirectory()} disabled={busy}>
            选择…
          </Button>
        </div>
      </div>

      {settings.engines.length === 0 ? (
        <div className="settings-field">
          <span className="settings-label">引擎</span>
          <p className="muted">还没有添加 WebGAL 引擎。项目骨架来自引擎，请先添加一个。</p>
          <Button appearance="secondary" onClick={onOpenEngineSettings}>
            去添加引擎
          </Button>
        </div>
      ) : (
        <>
          <div className="settings-field">
            <span className="settings-label">引擎</span>
            <Select value={engineId} options={engineOptions} disabled={busy} onChange={setEngineId} />
          </div>

          <div className="settings-field">
            <span className="settings-label">模板</span>
            <Select value={templateId} options={templateOptions} disabled={busy} onChange={setTemplateId} />
          </div>
        </>
      )}

      {target ? (
        <p className="dialog-hint" title={target}>
          {target}
        </p>
      ) : null}
      {error ? <p className="prompt-error">{error}</p> : null}
    </AppDialog>
  );
}
